        return;
    }

    if (descriptor.type == Type::singleton<bool>())
    {
        p.setValue<bool>(lua_toboolean(L, index) != 0);
        return;
    }

    if (descriptor.type == Type::singleton<float>())
    {
        p.setValue<float>(lua_tonumber(L, index));
        return;
    }

