        fi = d(h + j + 1)
        try:
            magic = d(fi)
        except Exception:
            continue
        if magic not in (0x19930520, 0x19930521, 0x19930522):
            continue
        n, um = d(fi + 4), d(fi + 8)
        out |= {d(um + 8 * k + 4) for k in range(n)} - {0}
        break
    return out


